:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --text: #e0e0e0;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --border: #0f3460;
  --high: #e94560;
  --medium: #f5a623;
  --low: #4e9f3d;
  --font: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: flex-start;
  min-height: 100vh;
  padding: 24px 16px;
}

.app {
  background: var(--card);
  border: 4px solid var(--border);
  border-radius: 0;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.5);
  padding: 24px;
  width: 100%;
  max-width: 600px;
}

h1 {
  font-size: 1.8rem;
  text-align: center;
  margin-bottom: 24px;
  color: var(--accent);
  text-shadow: 2px 2px 0 #000;
  letter-spacing: 2px;
}

.task-form {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 24px;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1 1 140px;
}

.input-group label {
  font-size: 0.9rem;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 1px;
}

input, select {
  font-family: var(--font);
  font-size: 1rem;
  padding: 10px 12px;
  background: var(--bg);
  border: 3px solid var(--border);
  color: var(--text);
  border-radius: 0;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

input:focus, select:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.3);
}

.btn {
  font-family: var(--font);
  font-size: 1rem;
  padding: 10px 20px;
  background: var(--accent);
  color: #fff;
  border: 3px solid var(--accent);
  cursor: pointer;
  border-radius: 0;
  transition: background 0.2s, transform 0.1s;
  text-transform: uppercase;
  letter-spacing: 1px;
  align-self: flex-end;
}

.btn:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

.btn:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

.btn:active {
  transform: translate(2px, 2px);
}

.btn-add {
  flex: 0 0 auto;
}

.filters {
  display: flex;
  gap: 8px;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.filter-btn {
  font-family: var(--font);
  font-size: 0.9rem;
  padding: 8px 16px;
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--border);
  cursor: pointer;
  border-radius: 0;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: background 0.2s, color 0.2s, border-color 0.2s;
}

.filter-btn:hover {
  background: var(--border);
}

.filter-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.filter-btn.active {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.filter-btn:active {
  transform: translate(2px, 2px);
}

.task-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.task-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: var(--bg);
  border: 3px solid var(--border);
  border-left-width: 8px;
  border-radius: 0;
  transition: background 0.2s, border-color 0.2s;
}

.task-item.priority-high {
  border-left-color: var(--high);
}

.task-item.priority-medium {
  border-left-color: var(--medium);
}

.task-item.priority-low {
  border-left-color: var(--low);
}

.task-item.completed {
  opacity: 0.6;
}

.task-item.completed .task-text {
  text-decoration: line-through;
}

.task-checkbox {
  width: 20px;
  height: 20px;
  cursor: pointer;
  accent-color: var(--accent);
  flex-shrink: 0;
}

.task-text {
  flex: 1;
  word-break: break-word;
  font-size: 1rem;
}

.task-priority-badge {
  font-size: 0.7rem;
  padding: 2px 6px;
  border: 2px solid;
  text-transform: uppercase;
  letter-spacing: 1px;
  flex-shrink: 0;
}

.priority-high .task-priority-badge {
  color: var(--high);
  border-color: var(--high);
}

.priority-medium .task-priority-badge {
  color: var(--medium);
  border-color: var(--medium);
}

.priority-low .task-priority-badge {
  color: var(--low);
  border-color: var(--low);
}

.btn-delete {
  background: none;
  border: 3px solid var(--accent);
  color: var(--accent);
  font-family: var(--font);
  font-size: 0.9rem;
  padding: 4px 10px;
  cursor: pointer;
  border-radius: 0;
  transition: background 0.2s, color 0.2s;
  flex-shrink: 0;
}

.btn-delete:hover {
  background: var(--accent);
  color: #fff;
}

.btn-delete:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

.btn-delete:active {
  transform: translate(2px, 2px);
}

.empty-message {
  text-align: center;
  color: var(--text);
  opacity: 0.6;
  padding: 24px;
  font-style: italic;
}

@media (max-width: 480px) {
  .task-form {
    flex-direction: column;
  }
  .btn-add {
    align-self: stretch;
  }
  .task-item {
    flex-wrap: wrap;
  }
  .task-priority-badge {
    order: -1;
  }
}

(function() {
  'use strict';

  const STORAGE_KEY = 'pixel-priority-tasks';

  const taskForm = document.getElementById('task-form');
  const taskInput = document.getElementById('task-input');
  const prioritySelect = document.getElementById('priority-select');
  const taskList = document.getElementById('task-list');
  const emptyMessage = document.getElementById('empty-message');
  const filterButtons = document.querySelectorAll('.filter-btn');

  let tasks = [];
  let currentFilter = 'all';

  const priorityOrder = { high: 0, medium: 1, low: 2 };

  function loadTasks() {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        tasks = JSON.parse(stored);
      }
    } catch (e) {
      tasks = [];
    }
  }

  function saveTasks() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
    } catch (e) {
      // ignore storage errors
    }
  }

  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
  }

  function render() {
    let filtered = tasks;
    if (currentFilter === 'active') {
      filtered = tasks.filter(t => !t.completed);
    } else if (currentFilter === 'completed') {
      filtered = tasks.filter(t => t.completed);
    }

    filtered.sort((a, b) => {
      if (a.completed !== b.completed) return a.completed ? 1 : -1;
      return priorityOrder[a.priority] - priorityOrder[b.priority];
    });

    taskList.innerHTML = '';

    if (filtered.length === 0) {
      emptyMessage.hidden = false;
    } else {
      emptyMessage.hidden = true;
      filtered.forEach(task => {
        const li = document.createElement('li');
        li.className = `task-item priority-${task.priority}${task.completed ? ' completed' : ''}`;
        li.dataset.id = task.id;

        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.className = 'task-checkbox';
        checkbox.checked = task.completed;
        checkbox.setAttribute('aria-label', `Mark "${task.text}" as ${task.completed ? 'incomplete' : 'complete'}`);
        checkbox.addEventListener('change', () => toggleTask(task.id));

        const textSpan = document.createElement('span');
        textSpan.className = 'task-text';
        textSpan.textContent = task.text;

        const badge = document.createElement('span');
        badge.className = 'task-priority-badge';
        badge.textContent = task.priority;

        const deleteBtn = document.createElement('button');
        deleteBtn.type = 'button';
        deleteBtn.className = 'btn-delete';
        deleteBtn.textContent = 'Delete';
        deleteBtn.setAttribute('aria-label', `Delete task "${task.text}"`);
        deleteBtn.addEventListener('click', () => deleteTask(task.id));

        li.appendChild(checkbox);
        li.appendChild(textSpan);
        li.appendChild(badge);
        li.appendChild(deleteBtn);
        taskList.appendChild(li);
      });
    }
  }

  function addTask(text, priority) {
    const trimmed = text.trim();
    if (!trimmed) return;
    tasks.push({
      id: generateId(),
      text: trimmed,
      priority: priority,
      completed: false
    });
    saveTasks();
    render();
  }

  function toggleTask(id) {
    const task = tasks.find(t => t.id === id);
    if (task) {
      task.completed = !task.completed;
      saveTasks();
      render();
    }
  }

  function deleteTask(id) {
    tasks = tasks.filter(t => t.id !== id);
    saveTasks();
    render();
  }

  function setFilter(filter) {
    currentFilter = filter;
    filterButtons.forEach(btn => {
      const isActive = btn.dataset.filter === filter;
      btn.classList.toggle('active', isActive);
      btn.setAttribute('aria-pressed', isActive.toString());
    });
    render();
  }

  taskForm.addEventListener('submit', function(e) {
    e.preventDefault();
    addTask(taskInput.value, prioritySelect.value);
    taskInput.value = '';
    taskInput.focus();
  });

  filterButtons.forEach(btn => {
    btn.addEventListener('click', () => setFilter(btn.dataset.filter));
  });

  loadTasks();
  render();
})();
